  Object.assign(L.en, {"ask_h": "Ask TrueWage", "ask_ph": "Type or speak your question", "ask_mic": "Speak", "ask_listening": "Listening…", "ask_send": "Ask", "ask_try": "Try asking", "ask_q1": "How much did I really make?", "ask_q2": "When and where should I work?", "ask_q3": "Should I take ₹40 for 3 km?", "ask_q4": "What if petrol gets 10% costlier?", "ask_q5": "Where does my money go?", "ask_src_ai": "Answered by Claude from your numbers", "ask_src_off": "Answered on your phone from your numbers (no AI service)", "ask_help": "I can answer about your earnings, best time and place, an order offer, costs, platforms, your daily goal, or fuel price changes. Try one of the questions below.", "ask_nodata": "Add your screenshots first, then I can answer from your numbers.", "ask_fuel": "If fuel gets {p}% costlier you would keep about {x} less every month: cash remaining {cash} a month instead of {base}.", "ask_none": "There is not enough data to say that yet. Add more days of screenshots.", "ask_unavail": "Claude could not be reached, so this answer was worked out on your phone.", "ns_h": "Next best step", "ns_vehicle": "We assumed a {vehicle}. Is that right? The correct vehicle and EMI make your number exact.", "ns_more": "Add screenshots from more days. After about 7 days TrueWage can show your best hours and places.", "ns_go": "Your next good window: {start}:00–{end}:00 at {zone} on {platform} (about {rate} an hour).", "ns_now_good": "You are in a good window now: {zone} on {platform} (about {rate} an hour).", "ns_share": "Share your receipt, or create your income statement for a bank.", "ns_yes": "Yes, correct", "acc_h": "How accurate is this?", "acc_range": "Your real pay is between {lo} and {hi} an hour, depending on how close our cost assumptions are to your bike.", "acc_measured": "From your screenshots (exact): pay, bonuses, cuts, distance, times.", "acc_assumed": "Our assumptions (you can set them): mileage, fuel price, repairs, unpaid riding, phone data, EMI.", "cal_field": "Real petrol cost (₹ per km, optional)", "cal_help": "Divide what you paid at your last fill by the km you rode on it. This makes your number more exact.", "tour_h": "Try these 4 things", "tour_1": "Press Listen: it reads your result aloud", "tour_2": "Ask: \"Should I take ₹40 for 3 km?\"", "tour_3": "Open Insights, then What-if, and drop the weakest hours", "tour_4": "Open Proof to create a bank-ready statement", "big_text": "Larger text", "mic_denied": "Voice input is not available on this browser. You can type instead.", "install_h": "Install on your phone", "install_p": "Open this page in Chrome and choose \"Add to Home screen\" to use it like an app, even offline.", "got_it": "Got it"});
  Object.assign(L.hi, {"ask_h": "TrueWage से पूछें", "ask_ph": "अपना सवाल लिखें या बोलें", "ask_mic": "बोलें", "ask_listening": "सुन रहा हूँ…", "ask_send": "पूछें", "ask_try": "ये पूछ कर देखें", "ask_q1": "मैंने असल में कितना कमाया?", "ask_q2": "मुझे कब और कहाँ काम करना चाहिए?", "ask_q3": "क्या मैं 3 किमी के ₹40 लूँ?", "ask_q4": "अगर पेट्रोल 10% महँगा हो जाए तो?", "ask_q5": "मेरा पैसा कहाँ जाता है?", "ask_src_ai": "आपके आँकड़ों से Claude का जवाब", "ask_src_off": "आपके फ़ोन पर आपके आँकड़ों से जवाब (AI सेवा नहीं)", "ask_help": "मैं आपकी कमाई, सबसे अच्छे समय और जगह, ऑर्डर ऑफ़र, खर्च, प्लेटफ़ॉर्म, रोज़ के लक्ष्य या पेट्रोल के दाम के बारे में बता सकता हूँ। नीचे का कोई सवाल आज़माएँ।", "ask_nodata": "पहले अपने स्क्रीनशॉट जोड़ें, फिर मैं आपके आँकड़ों से जवाब दे सकूँगा।", "ask_fuel": "अगर पेट्रोल {p}% महँगा हुआ तो हर महीने लगभग {x} कम बचेंगे: हाथ में {base} की जगह {cash} प्रति माह।", "ask_none": "अभी यह बताने के लिए पर्याप्त डेटा नहीं है। और दिनों के स्क्रीनशॉट जोड़ें।", "ask_unavail": "Claude से संपर्क नहीं हो सका, इसलिए यह जवाब आपके फ़ोन पर बनाया गया।", "ns_h": "अगला सबसे अच्छा कदम", "ns_vehicle": "हमने {vehicle} माना है। क्या यह सही है? सही वाहन और किस्त से आपका आँकड़ा सटीक होगा।", "ns_more": "और दिनों के स्क्रीनशॉट जोड़ें। लगभग 7 दिन बाद TrueWage आपके सबसे अच्छे समय और जगह दिखा सकता है।", "ns_go": "आपका अगला अच्छा समय: {start}:00–{end}:00, {zone}, {platform} (लगभग {rate} प्रति घंटा)।", "ns_now_good": "अभी अच्छा समय है: {zone}, {platform} (लगभग {rate} प्रति घंटा)।", "ns_share": "अपनी रसीद शेयर करें, या बैंक के लिए आय विवरण बनाएँ।", "ns_yes": "हाँ, सही है", "acc_h": "यह कितना सटीक है?", "acc_range": "आपकी असली कमाई प्रति घंटा {lo} से {hi} के बीच है; यह इस पर निर्भर है कि हमारे खर्च के अनुमान आपकी बाइक से कितने मिलते हैं।", "acc_measured": "आपके स्क्रीनशॉट से (सटीक): भुगतान, बोनस, कटौती, दूरी, समय।", "acc_assumed": "हमारे अनुमान (आप बदल सकते हैं): माइलेज, पेट्रोल का दाम, मरम्मत, बिना भुगतान सवारी, फ़ोन डेटा, किस्त।", "cal_field": "असली पेट्रोल खर्च (₹ प्रति किमी, वैकल्पिक)", "cal_help": "आख़िरी बार जितने रुपये का पेट्रोल भरवाया, उसे उस पर चलाए किमी से भाग दें। इससे आँकड़ा और सटीक होगा।", "tour_h": "ये 4 चीज़ें आज़माएँ", "tour_1": "‘सुनें’ दबाएँ: नतीजा बोलकर सुनाएगा", "tour_2": "पूछें: \"क्या मैं 3 किमी के ₹40 लूँ?\"", "tour_3": "Insights खोलें, फिर ‘अगर ऐसा हो’ में कमज़ोर समय हटाएँ", "tour_4": "Proof खोलकर बैंक के लिए विवरण बनाएँ", "big_text": "बड़ा टेक्स्ट", "mic_denied": "इस ब्राउज़र में आवाज़ से इनपुट उपलब्ध नहीं है। आप लिख सकते हैं।", "install_h": "फ़ोन में इंस्टॉल करें", "install_p": "इस पेज को Chrome में खोलें और \"Add to Home screen\" चुनें; फिर यह ऐप की तरह चलेगा, ऑफ़लाइन भी।", "got_it": "ठीक है"});
  Object.assign(L.te, {"ask_h": "TrueWage ని అడగండి", "ask_ph": "మీ ప్రశ్న రాయండి లేదా చెప్పండి", "ask_mic": "మాట్లాడండి", "ask_listening": "వింటున్నాను…", "ask_send": "అడగండి", "ask_try": "ఇవి అడిగి చూడండి", "ask_q1": "నేను నిజంగా ఎంత సంపాదించాను?", "ask_q2": "నేను ఎప్పుడు ఎక్కడ పని చేయాలి?", "ask_q3": "3 కి.మీ.కు ₹40 తీసుకోవాలా?", "ask_q4": "పెట్రోల్ 10% పెరిగితే?", "ask_q5": "నా డబ్బు ఎక్కడికి వెళ్తోంది?", "ask_src_ai": "మీ సంఖ్యల ఆధారంగా Claude సమాధానం", "ask_src_off": "మీ ఫోన్‌లో మీ సంఖ్యల నుండి సమాధానం (AI సేవ లేదు)", "ask_help": "మీ సంపాదన, ఉత్తమ సమయం-ప్రదేశం, ఆర్డర్ ఆఫర్, ఖర్చులు, ప్లాట్‌ఫార్మ్లు, రోజువారీ లక్ష్యం లేదా ఇంధన ధర మార్పుల గురించి చెప్పగలను. కింది ప్రశ్నలలో ఒకటి ప్రయత్నించండి.", "ask_nodata": "మొదట మీ స్క్రీన్‌షాట్లు జోడించండి, అప్పుడు మీ సంఖ్యలతో సమాధానం ఇవ్వగలను.", "ask_fuel": "ఇంధనం {p}% పెరిగితే ప్రతి నెలా సుమారు {x} తక్కువ మిగులుతుంది: నెలకు {base} కాకుండా {cash} చేతిలో మిగులుతుంది.", "ask_none": "అది చెప్పడానికి ఇంకా తగినంత డేటా లేదు. మరిన్ని రోజుల స్క్రీన్‌షాట్లు జోడించండి.", "ask_unavail": "Claude అందుబాటులో లేదు, అందువల్ల ఈ సమాధానం మీ ఫోన్‌లో లెక్కించాం.", "ns_h": "తదుపరి ఉత్తమ అడుగు", "ns_vehicle": "మేము {vehicle} అనుకున్నాం. ఇది సరైనదేనా? సరైన వాహనం, EMI ఇస్తే మీ సంఖ్య కచ్చితంగా వస్తుంది.", "ns_more": "మరిన్ని రోజుల స్క్రీన్‌షాట్లు జోడించండి. సుమారు 7 రోజుల తర్వాత TrueWage మీ ఉత్తమ సమయాలు, ప్రదేశాలు చూపగలదు.", "ns_go": "మీ తదుపరి మంచి సమయం: {start}:00–{end}:00, {zone}, {platform} (గంటకు సుమారు {rate}).", "ns_now_good": "ఇప్పుడు మంచి సమయం: {zone}, {platform} (గంటకు సుమారు {rate}).", "ns_share": "మీ రసీదు షేర్ చేయండి, లేదా బ్యాంకు కోసం ఆదాయ పత్రం తయారు చేయండి.", "ns_yes": "అవును, సరైనది", "acc_h": "ఇది ఎంత కచ్చితం?", "acc_range": "మీ అసలు సంపాదన గంటకు {lo} నుండి {hi} మధ్య ఉంటుంది — మా ఖర్చు అంచనాలు మీ బైక్‌కు ఎంత దగ్గరగా ఉన్నాయో దానిపై ఆధారపడి.", "acc_measured": "మీ స్క్రీన్‌షాట్ల నుండి (కచ్చితం): చెల్లింపు, బోనస్, కోతలు, దూరం, సమయాలు.", "acc_assumed": "మా అంచనాలు (మీరు మార్చవచ్చు): మైలేజ్, ఇంధన ధర, రిపేర్లు, చెల్లింపు లేని ప్రయాణం, ఫోన్ డేటా, EMI.", "cal_field": "అసలు పెట్రోల్ ఖర్చు (₹/కి.మీ., ఐచ్ఛికం)", "cal_help": "చివరిసారి పెట్రోల్కు చెల్లించిన డబ్బును, దానితో నడిపిన కి.మీ.తో భాగించండి. ఇది మీ సంఖ్యను మరింత కచ్చితం చేస్తుంది.", "tour_h": "ఈ 4 పనులు ప్రయత్నించండి", "tour_1": "‘వినండి’ నొక్కండి: ఫలితం చదివి వినిపిస్తుంది", "tour_2": "అడగండి: \"3 కి.మీ.కు ₹40 తీసుకోవాలా?\"", "tour_3": "Insights తెరిచి, ‘అయితే?’లో బలహీన సమయాలను తీసేయండి", "tour_4": "Proof తెరిచి బ్యాంకు కోసం పత్రం తయారు చేయండి", "big_text": "పెద్ద అక్షరాలు", "mic_denied": "ఈ బ్రౌజర్‌లో వాయిస్ ఇన్‌పుట్ అందుబాటులో లేదు. మీరు రాయవచ్చు.", "install_h": "ఫోన్‌లో ఇన్‌స్టాల్ చేయండి", "install_p": "ఈ పేజీని Chromeలో తెరిచి \"Add to Home screen\" ఎంచుకోండి; అప్పుడు యాప్ లాగా పనిచేస్తుంది, ఆఫ్‌లైన్‌లో కూడా.", "got_it": "సరే"});
  Object.assign(L.ta, {"ask_h": "TrueWage-ஐக் கேளுங்கள்", "ask_ph": "உங்கள் கேள்வியை எழுதுங்கள் அல்லது சொல்லுங்கள்", "ask_mic": "பேசுங்கள்", "ask_listening": "கேட்கிறேன்…", "ask_send": "கேள்", "ask_try": "இவற்றைக் கேட்டுப் பாருங்கள்", "ask_q1": "நான் உண்மையில் எவ்வளவு சம்பாதித்தேன்?", "ask_q2": "நான் எப்போது எங்கே வேலை செய்ய வேண்டும்?", "ask_q3": "3 கி.மீ.க்கு ₹40 எடுக்கலாமா?", "ask_q4": "பெட்ரோல் 10% உயர்ந்தால்?", "ask_q5": "என் பணம் எங்கே போகிறது?", "ask_src_ai": "உங்கள் எண்களிலிருந்து Claude பதில்", "ask_src_off": "உங்கள் போனில் உங்கள் எண்களிலிருந்து பதில் (AI சேவை இல்லை)", "ask_help": "உங்கள் வருமானம், சிறந்த நேரம்-இடம், ஆர்டர் ஆஃபர், செலவுகள், தளங்கள், தினசரி இலக்கு அல்லது எரிபொருள் விலை மாற்றம் பற்றி சொல்லுவேன். கீழே உள்ள கேள்விகளில் ஒன்றை முயற்சி செய்யுங்கள்.", "ask_nodata": "முதலில் உங்கள் ஸ்கிரீன்ஷாட்களைச் சேர்க்கவும், பிறகு உங்கள் எண்களிலிருந்து பதில் சொல்லுவேன்.", "ask_fuel": "எரிபொருள் {p}% உயர்ந்தால் மாதம் சுமார் {x} குறைவாக மிஞ்சும்: {base}-க்கு பதிலாக மாதம் {cash} கையில் மிஞ்சும்.", "ask_none": "அதைச் சொல்ல இன்னும் போதுமான தரவு இல்லை. மேலும் நாட்களின் ஸ்கிரீன்ஷாட்களைச் சேர்க்கவும்.", "ask_unavail": "Claude-ஐ அடைய முடியவில்லை, அதனால் இந்த பதில் உங்கள் போனில் கணக்கிட்டு சொல்லப்பட்டது.", "ns_h": "அடுத்த சிறந்த படி", "ns_vehicle": "நாங்கள் {vehicle} என்று எடுத்துக்கொண்டோம். இது சரியா? சரியான வாகனமும் EMI-யும் உங்கள் எண்ணைத் துல்லியமாக்கும்.", "ns_more": "மேலும் நாட்களின் ஸ்கிரீன்ஷாட்களைச் சேருங்கள். சுமார் 7 நாட்களுக்குப் பிறகு TrueWage உங்கள் சிறந்த நேரங்களையும் இடங்களையும் காட்டும்.", "ns_go": "உங்கள் அடுத்த நல்ல நேரம்: {start}:00–{end}:00, {zone}, {platform} (மணிக்கு சுமார் {rate}).", "ns_now_good": "இப்போது நல்ல நேரம்: {zone}, {platform} (மணிக்கு சுமார் {rate}).", "ns_share": "உங்கள் ரசீதைப் பகிருங்கள், அல்லது வங்கிக்கான வருமான அறிக்கையை உருவாக்குங்கள்.", "ns_yes": "ஆம், சரி", "acc_h": "இது எவ்வளவு துல்லியம்?", "acc_range": "உங்கள் உண்மை வருமானம் மணிக்கு {lo} முதல் {hi} வரை இருக்கும் — எங்கள் செலவு மதிப்பீடுகள் உங்கள் வாகனத்துடன் எவ்வளவு பொருந்துகின்றன என்பதைப் பொறுத்து.", "acc_measured": "உங்கள் ஸ்கிரீன்ஷாட்டிலிருந்து (துல்லியம்): தொகை, போனஸ், பிடித்தம், தூரம், நேரங்கள்.", "acc_assumed": "எங்கள் மதிப்பீடுகள் (நீங்கள் மாற்றலாம்): மைலேஜ், எரிபொருள் விலை, பழுது, பணம் இல்லாத ஓட்டம், போன் டேட்டா, EMI.", "cal_field": "உண்மை பெட்ரோல் செலவு (₹/கி.மீ., விருப்பம்)", "cal_help": "கடைசியாக பெட்ரோலுக்கு செலவிட்ட பணத்தை, அதில் ஓட்டிய கி.மீ.ஆல் வகுங்கள். இது உங்கள் எண்ணை இன்னும் துல்லியமாக்கும்.", "tour_h": "இந்த 4 விஷயங்களை முயற்சி செய்யுங்கள்", "tour_1": "‘கேளுங்கள்’ அழுத்துங்கள்: முடிவை வாசித்துக் காட்டும்", "tour_2": "கேளுங்கள்: \"3 கி.மீ.க்கு ₹40 எடுக்கலாமா?\"", "tour_3": "Insights திறந்து, ‘என்றால்?’ இல் பலவீன நேரங்களை நீக்குங்கள்", "tour_4": "Proof திறந்து வங்கிக்கான அறிக்கையை உருவாக்குங்கள்", "big_text": "பெரிய எழுத்து", "mic_denied": "இந்த உலாவியில் குரல் உள்ளீடு இல்லை. நீங்கள் எழுதலாம்.", "install_h": "போனில் நிறுவுங்கள்", "install_p": "இந்தப் பக்கத்தை Chrome-ல் திறந்து \"Add to Home screen\" தேர்வு செய்யுங்கள்; ஆப்பைப் போல ஆஃப்லைனிலும் பயன்படுத்தலாம்.", "got_it": "சரி"});
