  Object.assign(L.hi, {"sh_h": "अपनी शिफ़्ट ट्रैक करें", "sh_hint": "ऑनलाइन होते समय शुरू करें, खत्म होने पर रोकें। TrueWage आपके ऑनलाइन घंटे और असली चली दूरी, बिना भुगतान वाले किलोमीटर समेत, नापता है।", "sh_start": "शिफ़्ट शुरू करें", "sh_stop": "शिफ़्ट रोकें", "sh_running": "ऑनलाइन", "sh_km": "किमी चले", "sh_gps_off": "लोकेशन बंद है, इसलिए सिर्फ़ समय ट्रैक हो रहा है। दूरी नापने के लिए लोकेशन की अनुमति दें।", "sh_saved": "शिफ़्ट सेव हुई: {h} ऑनलाइन, {km} किमी।", "sh_unmatched": "{date} की शिफ़्ट: {h} ऑनलाइन, {km} किमी। उस दिन के स्क्रीनशॉट जोड़ें ताकि पता चले उसमें कितनी कमाई हुई।", "sh_measured": "बिना भुगतान की सवारी GPS से नापी गई: हर भुगतान वाले किमी पर {f} अतिरिक्त किमी ({n} शिफ़्ट)।", "sh_assumed": "बिना भुगतान की सवारी का अनुमान है ({f})। इसे नापने के लिए 3 शिफ़्ट ट्रैक करें और उनके स्क्रीनशॉट जोड़ें।", "sh_keep": "सवारी के दौरान TrueWage खुला रखें। आपका रास्ता कभी सेव नहीं होता, सिर्फ़ कुल दूरी।", "sh_platform": "आप किस ऐप पर काम कर रहे हैं", "sh_summary": "{n} शिफ़्ट ट्रैक हुईं · {h} घंटे · {km} किमी", "sh_badge": "नापा हुआ", "sh_gps_wait": "लोकेशन सिग्नल का इंतज़ार…"});
  Object.assign(L.te, {"sh_h": "మీ షిఫ్ట్‌ను ట్రాక్ చేయండి", "sh_hint": "ఆన్‌లైన్‌లోకి వెళ్లినప్పుడు మొదలుపెట్టండి, ముగించాక ఆపండి. TrueWage మీ ఆన్‌లైన్ గంటలను, చెల్లింపు లేని కిలోమీటర్లతో సహా మీరు నిజంగా నడిపిన దూరాన్ని కొలుస్తుంది.", "sh_start": "షిఫ్ట్ మొదలుపెట్టండి", "sh_stop": "షిఫ్ట్ ఆపండి", "sh_running": "ఆన్‌లైన్", "sh_km": "కి.మీ. నడిపారు", "sh_gps_off": "లొకేషన్ ఆఫ్‌లో ఉంది, కాబట్టి సమయం మాత్రమే ట్రాక్ అవుతోంది. దూరం కొలవడానికి లొకేషన్ అనుమతి ఇవ్వండి.", "sh_saved": "షిఫ్ట్ సేవ్ అయింది: {h} ఆన్‌లైన్, {km} కి.మీ.", "sh_unmatched": "{date} షిఫ్ట్: {h} ఆన్‌లైన్, {km} కి.మీ. అది ఎంత సంపాదించిందో చూడటానికి ఆ రోజు స్క్రీన్‌షాట్లు జోడించండి.", "sh_measured": "చెల్లింపు లేని ప్రయాణం GPS తో కొలిచాం: చెల్లింపు ఉన్న ప్రతి కి.మీ.కు {f} అదనపు కి.మీ. ({n} షిఫ్ట్‌లు).", "sh_assumed": "చెల్లింపు లేని ప్రయాణం అంచనా మాత్రమే ({f}). కొలవడానికి 3 షిఫ్ట్‌లు ట్రాక్ చేసి వాటి స్క్రీన్‌షాట్లు జోడించండి.", "sh_keep": "ప్రయాణిస్తున్నప్పుడు TrueWage తెరిచి ఉంచండి. మీ దారి ఎప్పుడూ సేవ్ కాదు, మొత్తం దూరం మాత్రమే.", "sh_platform": "మీరు ఏ యాప్‌లో పని చేస్తున్నారు", "sh_summary": "{n} షిఫ్ట్‌లు ట్రాక్ అయ్యాయి · {h} గంటలు · {km} కి.మీ.", "sh_badge": "కొలిచినది", "sh_gps_wait": "లొకేషన్ సిగ్నల్ కోసం వేచి చూస్తున్నాం…"});
  Object.assign(L.ta, {"sh_h": "உங்கள் ஷிப்டைக் கண்காணியுங்கள்", "sh_hint": "ஆன்லைனுக்கு வரும்போது தொடங்குங்கள், முடிந்ததும் நிறுத்துங்கள். TrueWage உங்கள் ஆன்லைன் மணி நேரத்தையும், பணம் இல்லாத கிலோமீட்டர் உட்பட நீங்கள் உண்மையில் ஓட்டிய தூரத்தையும் அளக்கிறது.", "sh_start": "ஷிப்டைத் தொடங்கு", "sh_stop": "ஷிப்டை நிறுத்து", "sh_running": "ஆன்லைன்", "sh_km": "கி.மீ. ஓட்டினீர்கள்", "sh_gps_off": "இருப்பிடம் அணைந்துள்ளது, அதனால் நேரம் மட்டுமே கண்காணிக்கப்படுகிறது. தூரத்தை அளக்க இருப்பிட அனுமதி கொடுங்கள்.", "sh_saved": "ஷிப்ட் சேமிக்கப்பட்டது: {h} ஆன்லைன், {km} கி.மீ.", "sh_unmatched": "{date} ஷிப்ட்: {h} ஆன்லைன், {km} கி.மீ. அது எவ்வளவு சம்பாதித்தது என்று பார்க்க அந்த நாளின் ஸ்கிரீன்ஷாட்களைச் சேருங்கள்.", "sh_measured": "பணம் இல்லாத ஓட்டம் GPS மூலம் அளக்கப்பட்டது: பணம் கிடைக்கும் ஒவ்வொரு கி.மீ.க்கும் {f} கூடுதல் கி.மீ. ({n} ஷிப்ட்கள்).", "sh_assumed": "பணம் இல்லாத ஓட்டம் மதிப்பீடு மட்டுமே ({f}). அளக்க 3 ஷிப்ட்களைக் கண்காணித்து அவற்றின் ஸ்கிரீன்ஷாட்களைச் சேருங்கள்.", "sh_keep": "ஓட்டும்போது TrueWage-ஐத் திறந்து வைத்திருங்கள். உங்கள் பாதை ஒருபோதும் சேமிக்கப்படாது, மொத்த தூரம் மட்டுமே.", "sh_platform": "நீங்கள் எந்த ஆப்பில் வேலை செய்கிறீர்கள்", "sh_summary": "{n} ஷிப்ட்கள் கண்காணிக்கப்பட்டன · {h} மணி · {km} கி.மீ.", "sh_badge": "அளக்கப்பட்டது", "sh_gps_wait": "இருப்பிட சிக்னலுக்காக காத்திருக்கிறேன்…"});
