  Object.assign(L.te, {"pd_h": "నా రోజు ప్లాన్", "pd_goal": "ఈరోజు చేతిలో మిగిలే లక్ష్యం (₹)", "pd_seg": "{start}:00–{end}:00 · {platform} · {zone} · సుమారు {rate}/గంట", "pd_total": "మీ సొంత ఉత్తమ సమయాల నుండి {h} గంటల్లో సుమారు {x}.", "pd_short": "మీ చరిత్ర ప్రకారం {h} గంటల్లో సుమారు {x} వస్తుంది. {goal} చేరుకోవడానికి ఇంకా కొన్ని మంచి సమయాల డేటా కావాలి.", "pd_none": "ప్లాన్ చేయడానికి ఇంకా తగినంత చరిత్ర లేదు. మరికొన్ని రోజుల స్క్రీన్‌షాట్లు జోడించండి.", "a_switch": "{daypart}లో {from}లో మీకు {a}/గంట వస్తుంది. అదే సమయంలో {to}లో మీరు {b}/గంట సంపాదించారు. అక్కడికి వెళ్లి చూడండి.", "a_switch_city": "{daypart}లో {from}లో మీకు {a}/గంట వస్తుంది. ఆ సమయంలో {to}లో రైడర్లు సుమారు {b}/గంట సంపాదిస్తారు (సిమ్యులేటెడ్ నగర డేటా). అక్కడికి వెళ్లి చూడండి.", "wk_h": "ఈ వారం", "wk_sum": "{days} రోజులు, చేతిలో {cash}, గంటకు {hr}.", "wk_win_up": "శుభవార్త: మీ అసలు సంపాదన గత వారం కంటే గంటకు {d} పెరిగింది.", "wk_win_best": "శుభవార్త: మీ అత్యుత్తమ రోజు {date} ({cash} చేతిలో).", "wk_fix_wait": "సరిదిద్దండి: మీ ఆన్‌లైన్ సమయంలో {pct}% వేచి చూసేదే. రద్దీ ఎక్కువ ఉన్న ప్రాంతాలను ఎంచుకోండి.", "wk_fix_skip": "సరిదిద్దండి: {daypart}లో {zone} వదిలేయండి. అక్కడ గంటకు {rate} మాత్రమే.", "wk_none": "వారాంతపు కోచ్‌కు కనీసం 8 రోజుల డేటా కావాలి. మరిన్ని స్క్రీన్‌షాట్లు జోడించండి లేదా మరిన్ని షిఫ్ట్‌లు ట్రాక్ చేయండి.", "sg_coach": "ఈ వారం", "sg_weeks": "వారాలు", "dm_hyd": "డెమో రైడర్ · హైదరాబాద్", "dm_blr": "డెమో రైడర్ · బెంగళూరు", "city_pick": "నగరం", "week_of": "{from} నుండి ప్రారంభమైన వారం", "wk_vs": "గత వారంతో పోల్చితే", "wk_up": "గంటకు {d} పెరిగింది", "wk_down": "గంటకు {d} తగ్గింది"});
  Object.assign(L.ta, {"pd_h": "என் நாள் டிட்டம்", "pd_goal": "இன்றைய கையில் மிஞ்சும் இலக்கு (₹)", "pd_seg": "{start}:00–{end}:00 · {platform} · {zone} · மணிக்கு சுமார் {rate}", "pd_total": "உங்கள் சொந்த சிறந்த நேரங்களிலிருந்து {h} மணியில் சுமார் {x}.", "pd_short": "உங்கள் வரலாற்றின் படி {h} மணியில் சுமார் {x} கிடைக்கும். {goal}-ஐ அடைய இன்னும் அதிக நல்ல நேரங்கள் தரவு தேவை.", "pd_none": "திட்டமிட இன்னும் போதுமான வரலாறு இல்லை. சில நாட்களின் ஸ்கிரீன்ஷாட்களைச் சேர்க்கவும்.", "a_switch": "{daypart}-ல் {from}-ல் உங்களுக்கு {a}/மணி கிடைக்கிறது. அதே நேரத்தில் {to}-ல் {b}/மணி சம்பாதித்தீர்கள். அங்கே செல்லிப் பாருங்கள்.", "a_switch_city": "{daypart}-ல் {from}-ல் உங்களுக்கு {a}/மணி கிடைக்கிறது. அதே நேரத்தில் {to}-ல் ரைடர்கள் சுமார் {b}/மணி சம்பாதிக்கிறார்கள் (சிமுலேட்டட் நகர தரவு). அங்கே செல்லிப் பாருங்கள்.", "wk_h": "இந்த வாரம்", "wk_sum": "{days} நாட்கள், {cash} கையில், மணிக்கு {hr}.", "wk_win_up": "நல்ல செய்தி: உங்கள் உண்மை வருமானம் கடந்த வாரத்தை விட மணிக்கு {d} உயர்ந்துள்ளது.", "wk_win_best": "நல்ல செய்தி: உங்கள் சிறந்த நாள் {date} ({cash} கையில்).", "wk_fix_wait": "சரிசெய்யுங்கள்: உங்கள் ஆன்லைன் நேரத்தில் {pct}% காத்திருப்பில் போகிறது. அதிக ஆர்டர் உள்ள பகுதிகளைத் தேர்ந்தெடுங்கள்.", "wk_fix_skip": "சரிசெய்யுங்கள்: {daypart}-ல் {zone}-ஐ விடுங்கள். அங்கே மணிக்கு {rate} மட்டுமே.", "wk_none": "வாராந்திர பயிற்றுனருக்கு குறைந்தது 8 நாட்களின் தரவு தேவை. மேலும் ஸ்கிரீன்ஷாட்களைச் சேர்க்கவும் அல்லது மேலும் ஷிப்ட்களைக் கண்காணிக்கவும்.", "sg_coach": "இந்த வாரம்", "sg_weeks": "வாரங்கள்", "dm_hyd": "டெமோ ரைடர் · ஹைதராபாத்", "dm_blr": "டெமோ ரைடர் · பெங்களூரு", "city_pick": "நகரம்", "week_of": "{from} முதல் தொடங்கும் வாரம்", "wk_vs": "கடந்த வாரத்துடன் ஒப்பிட்டால்", "wk_up": "மணிக்கு {d} உயர்வு", "wk_down": "மணிக்கு {d} குறைவு"});
